    index++;if(index%25==0){var progress=c.Capture();var n=progress["nodeSession"]["runtime"];File.WriteAllText(Qa+"fresh-execution-progress.json",new JObject{["commandsExecuted"]=index,["totalCommands"]=inputs.Count,["tick"]=n["state"]["direct"]["clock"]["completedSteps"].DeepClone(),["eventRecords"]=((JArray)n["originalEvents"]["records"]).Count,["elapsedSeconds"]=(DateTime.UtcNow-start).TotalSeconds}.ToString());yield return null;}
